Use a count to distinguish empty from full: empty means count == 0, and full means count == 17, even though head == tail in both cases. The invariant is 0 <= count <= 17, with tail == (head + count) % 17; rejected operations leave the queue unchanged. Compile as C++17 without defining NDEBUG to run the assertions.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -1;

    assert(queue.empty());
    assert(!queue.pop(value));
    assert(value == -1);

    // All 17 slots are usable.
    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }
    assert(queue.full());

    // Rejection must preserve both size and every queued value.
    assert(!queue.push(999));
    assert(queue.size() == 17);
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    // Move head forward, then refill across the array boundary.
    for (int i = 0; i < 12; ++i) {
        assert(queue.push(i));
    }
    for (int i = 0; i < 8; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 12; i < 25; ++i) {
        assert(queue.push(i));
    }
    assert(queue.full());
    assert(!queue.push(999));
    for (int i = 8; i < 25; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.empty());
    assert(!queue.pop(value));

    std::cout << "All tests passed\n";
}
```

The lower median is 4: sorting gives [1,2,4,4,7,9]. Copy the input and use `std::nth_element`, so the caller’s array remains unchanged.

For odd size n = 2m + 1, the median’s zero-based index is m. For even size n = 2m, the lower middle index is m − 1. Both equal floor((n − 1)/2); `nth_element` places the value that would occupy that index in sorted order, including when duplicates occur.

Compile with C++17 and without `NDEBUG` to run the assertions.

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

int lower_median(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }

    std::vector<int> copy = input;
    const std::size_t index = (copy.size() - 1) / 2;
    auto selected = copy.begin() +
        static_cast<std::vector<int>::difference_type>(index);
    std::nth_element(copy.begin(), selected, copy.end());
    return *selected;
}

int main() {
    const auto check = [](std::vector<int> input, int expected) {
        const auto original = input;
        const int result = lower_median(input);
        assert(result == expected);
        assert(input == original);
    };

    check({9, 1, 4, 4, 7, 2}, 4); // Requested case and duplicates.
    check({5, 5, 5, 5}, 5);       // All values equal.
    check({9, 1, 7, 3, 5}, 5);    // Odd size.
    check({8, 2, 6, 4}, 4);       // Even size: lower middle.
    check({42}, 42);              // Singleton.

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lower_median(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());

    std::cout << "All tests passed\n";
    return 0;
}
```

No. A successful retry can store a stale desired value and lose an increment.

Start with counter = 0. Threads A and B both read expected = 0 and compute desired = 1:
1. A successfully compares 0 and stores 1, finishing its increment.
2. B compares against 0 and fails because the counter is 1. Its expected becomes 1, but desired remains 1.
3. B retries, successfully compares against 1 and stores 1, finishing without increasing the counter. Two increments have completed, but the counter is only 1.

Recompute desired before every attempt. A spurious failure also retries safely: expected receives the observed value, and the next attempt recomputes its successor. Each successful compare-exchange then increments exactly the value it matched; relaxed ordering suffices for this standalone counter, not for publishing unrelated data.

Compile with `g++ -std=c++17 -O2 -pthread main.cpp -o counter`, without defining `NDEBUG`, and run `./counter`.

```cpp
#include <atomic>
#include <cassert>
#include <iostream>
#include <thread>
#include <vector>

// Precondition: the counter cannot reach INT_MAX during these increments.
void increment(std::atomic<int>& counter) {
    int expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const int desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure, including spurious failure, updates expected.
        // Recompute desired on the next iteration.
    }
}

int main() {
    constexpr int thread_count = 4;
    constexpr int increments_per_thread = 100000;
    constexpr int expected_total =
        thread_count * increments_per_thread;

    std::atomic<int> counter{0};
    std::vector<std::thread> threads;
    threads.reserve(thread_count);

    for (int t = 0; t < thread_count; ++t) {
        threads.emplace_back([&counter] {
            for (int i = 0; i < increments_per_thread; ++i) {
                increment(counter);
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    const int actual = counter.load(std::memory_order_relaxed);
    assert(actual == expected_total);
    std::cout << "All tests passed: " << actual << '\n';
    return 0;
}
```
